      var list = (r && r.shifts) || [];
      if (!list.length) { status('Last week has no shifts to copy.', 'err'); return; }
      var ok = S.employees.reduce(function (o, e) { if (e.active !== false) o[e.id] = 1; return o; }, {});
      var keep = list.filter(function (s) { return ok[s.emp]; });
