      C.sales = {}; (r[1].error ? [] : r[1].data || []).forEach(function (s) { C.sales[s.month] = s; });
      C.invOk = !r[2].error; C.inv = r[2].error ? [] : (r[2].data || []).filter(function (x) { return x.active !== false; });
