      if ((m = /^allergens?\s*[:\-]\s*(.+)$/i.exec(bare))) { x.allergens = m[1].trim(); return; }
      if ((m = /^category\s*[:\-]\s*(.+)$/i.exec(bare))) { x.category = m[1].trim(); return; }
